-- Existing free-worker schema, recovered from the live D1 database.
CREATE TABLE IF NOT EXISTS updates (id INTEGER PRIMARY KEY, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL DEFAULT 0, ready_at INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, error TEXT, outbound TEXT, method TEXT);
CREATE TABLE IF NOT EXISTS preferences (user_id INTEGER PRIMARY KEY, opted_out INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (user_id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rewards (event_key TEXT PRIMARY KEY, user_id INTEGER NOT NULL, amount INTEGER NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quota (event_key TEXT PRIMARY KEY, user_id INTEGER NOT NULL, thread_id INTEGER NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS context (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, chat_id INTEGER NOT NULL, thread_id INTEGER NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS polls (poll_id TEXT PRIMARY KEY, correct INTEGER NOT NULL, expires_at INTEGER NOT NULL, chat_id INTEGER NOT NULL, thread_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS answers (poll_id TEXT NOT NULL, user_id INTEGER NOT NULL, option_id INTEGER NOT NULL, PRIMARY KEY(poll_id,user_id));
